<label>Room number<input name="room_number" required value="{{ old('room_number',$room?->room_number) }}"></label><label>Room type<select name="room_type_id" required><option value="">Select type</option>@foreach($types as $type)<option value="{{ $type->id }}" @selected(old('room_type_id',$room?->room_type_id)==$type->id)>{{ $type->name }}</option>@endforeach</select></label><label>Room name<input name="name" value="{{ old('name',$room?->name) }}"></label><label>Building<input name="building" value="{{ old('building',$room?->building) }}"></label><label>Floor<input name="floor" value="{{ old('floor',$room?->floor) }}"></label><label>Room status<select name="status">@foreach(['available','reserved','occupied','dirty','cleaning','inspected','maintenance','blocked','out_of_order'] as $s)<option @selected(old('status',$room?->status?->value ?? 'available')===$s) value="{{ $s }}">{{ ucwords(str_replace('_',' ',$s)) }}</option>@endforeach</select></label><label>Housekeeping<select name="housekeeping_status">@foreach(['clean','dirty','cleaning','inspected'] as $s)<option @selected(old('housekeeping_status',$room?->housekeeping_status ?? 'clean')===$s)>{{ $s }}</option>@endforeach</select></label><label class="span-2">Notes<textarea name="notes">{{ old('notes',$room?->notes) }}</textarea></label>
